Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='flakymeansbug', at=datetime(2026, 11, 5, 0, 0, 0), actor='assistant', title='A flaky test is a bug: name its cause, then fix it there', body="A test that fails and then passes on the same tree is instrumented, not retried: keep the failure's artifacts, log what the code did, loop it under the gate's load, and name the cause with evidence before fixing it. The fix goes where the cause is: in the app when a person could meet it, in the test when only the test is wrong. Raising a timeout or adding a retry without a named cause is not a fix.", rationale='2026-11-05: a scene called flaky twice was the app drawing an old page over a new one (fixed in #351); a person tapping a tab would have met it.', supersedes=()))